BEGIN;

-- Bring production.orders in line with staging: the checkout-flow `currency` column.
-- Additive only. Non-volatile default => no table rewrite on 4,800 rows.
SELECT production.taper_add_column('production', 'orders', 'currency', 'text', 'USD', true);

-- Existing rows must all have been backfilled by the default.
DO $$
DECLARE n bigint;
BEGIN
    SELECT count(*) INTO n FROM production.orders WHERE currency IS DISTINCT FROM 'USD';
    IF n <> 0 THEN RAISE EXCEPTION 'backfill check failed: % rows not USD', n; END IF;
END $$;

COMMIT;
SQL
